import{_ as t,o,c as r,ah as a}from"./chunks/framework.C-FRNfAJ.js";const p=JSON.parse('{"title":"Training your teams on quote","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/entreprises/formation-sur-devis.md","filePath":"src/en/guide/entreprises/formation-sur-devis.md"}'),n={name:"en/guide/entreprises/formation-sur-devis.md"};function s(i,e,d,u,c,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="training-your-teams-on-quote" tabindex="-1">Training your teams on quote <a class="header-anchor" href="#training-your-teams-on-quote" aria-label="Permalink to &quot;Training your teams on quote&quot;">​</a></h1><p>A company can order a catalogue training for its employees: this is <strong>training on quote</strong>. It gives rise to one or more <strong>dedicated cohorts</strong>, reserved for the company.</p><p>There is no candidature, no individual agreement and no invoice per employee: the company receives <strong>a quote, then a single invoice</strong>.</p><h2 id="submitting-a-request" tabindex="-1">Submitting a request <a class="header-anchor" href="#submitting-a-request" aria-label="Permalink to &quot;Submitting a request&quot;">​</a></h2><p>An organization account is not required: the contact person, with an individual account, can make the request. It is done in two ways:</p><ul><li>from the <strong>NextBoxx website</strong>;</li><li>from Kura, <strong>Journeys → My company requests → New request</strong>, choosing the type &quot;Training for my teams&quot;.</li></ul><p>Give the company name, the catalogue program, the format, the number of people, the wished start (optional) and a message. The request receives a <code>DEM-NB</code> reference and the Pedagogical Coordinator is notified.</p><h2 id="the-quote" tabindex="-1">The quote <a class="header-anchor" href="#the-quote" aria-label="Permalink to &quot;The quote&quot;">​</a></h2><p>The Coordinator studies the request and sends you a <strong>quote</strong> (<code>DEV-NB</code>) by e-mail, as a PDF: program, format, headcount, dates, pace and total amount in FCFA. Beyond <strong>15 learners</strong>, the quote provides <strong>one cohort per slice of 15</strong>. Only one quote awaits an answer at a time.</p><p>In <strong>My company requests</strong>, the request page shows where things stand: &quot;Received&quot;, &quot;In progress&quot;, &quot;Quote sent&quot;, &quot;Accepted&quot; or &quot;Closed&quot;.</p><h3 id="accepting-or-refusing" tabindex="-1">Accepting or refusing <a class="header-anchor" href="#accepting-or-refusing" aria-label="Permalink to &quot;Accepting or refusing&quot;">​</a></h3><p>When the quote is ready, you accept or refuse it from the request, before its start date. The Coordinator can also record on your behalf an acceptance received by another means.</p><ul><li><strong>Refusal.</strong> Say why if you wish: the request stays in progress, and the Coordinator can send you a revised quote or close the request.</li><li><strong>Acceptance.</strong> It opens your dedicated cohorts at once and issues the <strong>single invoice</strong>, for the amount of the quote, to your company name, <strong>due on the first day of the training</strong>.</li></ul><h2 id="adding-your-learners" tabindex="-1">Adding your learners <a class="header-anchor" href="#adding-your-learners" aria-label="Permalink to &quot;Adding your learners&quot;">​</a></h2><p>Once the cohorts are open, add your employees (their name and e-mail address) from the request, <strong>15 at most per cohort</strong>, as long as the cohort is neither completed nor cancelled.</p><p>For each employee, Kura creates or reuses an account, enrols them <strong>directly and actively</strong>, gives them the Learner role, sends them their welcome booklet and opens their access to Sève. They receive their access by e-mail.</p><p>The Coordinator can remove a learner by recording a drop-out.</p><h2 id="payment-and-its-delays" tabindex="-1">Payment and its delays <a class="header-anchor" href="#payment-and-its-delays" aria-label="Permalink to &quot;Payment and its delays&quot;">​</a></h2><p>The invoice follows the usual timeline: reminders before the due date, a reminder the next day, follow-up at D+7, overdue and 15-day moratorium at D+15.</p><p>At <strong>D+30</strong> without payment, the enrolments of your dedicated cohorts and <strong>their access to Sève are suspended</strong>. The contact is notified. Payment restores them. A learner added during the non-payment starts suspended. Your employees&#39; accounts stay active.</p><p>For a learner of a dedicated cohort, the certificate&#39;s &quot;balance paid&quot; condition is met when <strong>the request&#39;s invoice is paid</strong>.</p>',21)])])}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
